import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { fetchRecommendations } from '../redux/slices/recommendationSlice';
import SearchBar from '../components/SearchBar';
import Questionnaire from '../components/Questionnaire';
import MovieCard from '../components/MovieCard';

const Matchmaker = () => {
    const dispatch = useDispatch();

    // Redux Store'dan (Merkezi Durum Yönetimi) verileri çekiyoruz
    const { recommendations, status, error } = useSelector((state) => state.recommendations);

    // Sayfa içi (Local) durumlar
    const [favoriteMovies, setFavoriteMovies] = useState([]);
    const [moodProfile, setMoodProfile] = useState(null);

    // Arama çubuğundan film eklendiğinde çalışır
    const handleAddFavorite = (movie) => {
        // Aynı filmi iki kez eklemeyi engelle
        if (!favoriteMovies.find(m => m.id === movie.id)) {
            setFavoriteMovies([...favoriteMovies, movie]);
        }
    };

    // Anketi doldurup "Kaydet" dendiğinde çalışır
    const handleProfileSubmit = (profile) => {
        setMoodProfile(profile);
    };

    // "Önerileri Getir" butonuna tıklandığında çalışır (DSD Sequence Diagram - Adım 2) [cite: 147]
    const handleGenerateRecommendations = () => {
        if (favoriteMovies.length === 0) {
            alert("Lütfen en az bir favori film seçin!");
            return;
        }

        // Backend'in beklediği sadece ID listesidir
        const favoriteMovieIds = favoriteMovies.map(m => m.id);

        // Redux üzerinden asenkron API çağrısını (Thunk) başlat
        // (DSD Sequence Diagram - Adım 3) [cite: 148]
        dispatch(fetchRecommendations({ favoriteMovieIds, moodProfile }));
    };

    return (
        <div style={{ padding: '40px', maxWidth: '1200px', margin: '0 auto' }}>
            <h2>Film Eşleştirici (Matchmaker)</h2>

            <div style={{ display: 'flex', gap: '40px', flexWrap: 'wrap' }}>

                {/* Sol Sütun: Girdi Alanları */}
                <div style={{ flex: '1', minWidth: '300px' }}>

                    {/* Adım 1: Favori Filmler */}
                    <div style={{ marginBottom: '30px' }}>
                        <h3>1. Sevdiğiniz Filmleri Ekleyin</h3>
                        <SearchBar onAddFavorite={handleAddFavorite} />

                        {/* Seçilen Filmlerin Listesi */}
                        <ul style={{ listStyleType: 'none', padding: 0 }}>
                            {favoriteMovies.map((movie) => (
                                <li key={movie.id} style={styles.listItem}>
                                    {movie.title}
                                    <button
                                        onClick={() => setFavoriteMovies(favoriteMovies.filter(m => m.id !== movie.id))}
                                        style={styles.deleteButton}
                                    >
                                        Kaldır
                                    </button>
                                </li>
                            ))}
                        </ul>
                    </div>

                    {/* Adım 2: Ruh Hali Anketi */}
                    <div style={{ marginBottom: '30px' }}>
                        <h3>2. Ruh Halinizi Belirleyin (Opsiyonel)</h3>
                        <Questionnaire onSubmitProfile={handleProfileSubmit} />
                        {moodProfile && <p style={{ color: 'green', marginTop: '10px' }}>✅ Profil kaydedildi.</p>}
                    </div>

                    {/* Adım 3: İşlemi Başlat */}
                    <button
                        onClick={handleGenerateRecommendations}
                        disabled={status === 'loading'}
                        style={{...styles.generateButton, opacity: status === 'loading' ? 0.7 : 1}}
                    >
                        {status === 'loading' ? 'Yapay Zeka Düşünüyor...' : 'Önerileri Getir'}
                    </button>

                    {/* Hata Mesajı */}
                    {status === 'failed' && <p style={{ color: 'red' }}>Hata: {error}</p>}
                </div>

                {/* Sağ Sütun: Öneri Sonuçları (DSD Adım 9) */}
                <div style={{ flex: '2', minWidth: '400px' }}>
                    <h3>Senin İçin Seçilenler</h3>

                    {status === 'idle' && <p style={{ color: '#666' }}>Önerileri görmek için seçimlerinizi yapın ve butona tıklayın.</p>}

                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: '20px' }}>
                        {recommendations.map((result, index) => (
                            <MovieCard key={result.movie.id || index} movie={result.movie} score={result.score} />
                        ))}
                    </div>
                </div>

            </div>
        </div>
    );
};

const styles = {
    listItem: {
        display: 'flex',
        justifyContent: 'space-between',
        padding: '10px',
        backgroundColor: '#f1f1f1',
        marginBottom: '8px',
        borderRadius: '4px'
    },
    deleteButton: {
        backgroundColor: 'red',
        color: 'white',
        border: 'none',
        borderRadius: '4px',
        cursor: 'pointer'
    },
    generateButton: {
        width: '100%',
        padding: '15px',
        backgroundColor: '#007BFF',
        color: '#fff',
        border: 'none',
        borderRadius: '8px',
        fontSize: '18px',
        fontWeight: 'bold',
        cursor: 'pointer',
        marginTop: '20px'
    }
};

export default Matchmaker;
